const app=document.querySelector('#app');
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function request(url,options){const r=await fetch(url,options);const b=await r.json();if(!r.ok)throw Error(b.error||'Request failed');return b}
const post=(url,body={})=>request(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
async function showList(error=''){const projects=await request('/api/projects');const filter=new URLSearchParams(location.search).get('filter')||'Active';const shown=projects.filter(p=>Boolean(p.archived)===(filter==='Archived'));
app.innerHTML=`<h1>Workboard</h1><label>Project filter<select id="project-filter"><option${filter==='Active'?' selected':''}>Active</option><option${filter==='Archived'?' selected':''}>Archived</option></select></label><form id="create-form"><label>Project name<input name="name" type="text" autocomplete="off"></label><button>Create project</button></form><div id="message" role="alert" aria-live="polite">${esc(error)}</div><section class="project-list" aria-label="Projects">${shown.map(p=>`<div class="project-row" data-testid="project-row"><span>${esc(p.name)}</span><span class="summary" data-testid="project-summary">${p.completed_count}/${p.total_count} completed</span><div class="actions"><button type="button" data-open="${esc(p.id)}">Open project</button>${p.archived?`<button type="button" data-action="restore" data-id="${esc(p.id)}">Restore project</button>`:`<button type="button" data-action="archive" data-id="${esc(p.id)}">Archive project</button>`}</div></div>`).join('')}</section>`;
