app.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{history.pushState({},'',`/projects/${encodeURIComponent(b.dataset.open)}`);render()});
app.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{await post(`/api/projects/${encodeURIComponent(b.dataset.id)}/${b.dataset.action}`);showList()});}
