app.querySelector('.back').onclick=back;const apply=()=>app.querySelectorAll('.task-row').forEach(row=>{const checked=row.querySelector('input').checked,f=app.querySelector('#task-filter').value;row.hidden=f==='Open'?checked:f==='Completed'?!checked:false});app.querySelector('#task-filter').onchange=apply;apply();
app.querySelectorAll('[data-task]').forEach(box=>box.onchange=async()=>{await request(`/api/projects/${encodeURIComponent(id)}/tasks/${encodeURIComponent(box.dataset.task)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({completed:box.checked})});apply()});
app.querySelector('#task-form').onsubmit=async e=>{e.preventDefault();try{await post(`/api/projects/${encodeURIComponent(id)}/tasks`,{title:new FormData(e.currentTarget).get('title')});showProject(id)}catch(x){app.querySelector('#task-message').textContent=x.message}};
